Convert this imperative JavaScript bubble sort to a functional sort:

const arr = nums.slice();
for (let i = 0; i < arr.length; i++) {
  for (let j = 0; j < arr.length - i - 1; j++) {
    if (arr[j] > arr[j + 1]) {
      const t = arr[j];
      arr[j] = arr[j + 1];
      arr[j + 1] = t;
    }
  }
}

